  const pixelToolArmed =
    pixelTool !== null && !pixelBusy && selected?.type === "image" && !selectedContentMutationLocked;
  // 마칭앤츠 오버레이용 프레임/선택 — 이미지 요소가 아닐 땐 null(오버레이 미마운트).
  const pixelOverlayFrame: SelectionFrame | null =
    selected?.type === "image"
      ? { x: selected.x, y: selected.y, width: selected.width, height: selected.height, rotation: selected.rotation }
      : null;
  const pixelOverlaySel = pixelSel && (pixelSel.subpaths.length > 0 || pixelSel.invert) ? pixelSel : null;
  // 크롭 모드 무장(이미지 요소 선택 + 크롭 rect 존재) — 무장 중엔 스테이지 드래그를 크롭 rect
  // 조작으로 가로채고, 요소 드래그/클릭 선택 전환을 함께 잠근다(픽셀 선택 도구와 동일 정책).
  const cropArmed =
    cropRect !== null && selected?.type === "image" && !selectedContentMutationLocked;
  // 패널 손그림 컷 무장(패널 선택 + 도구 on, 잠긴 패널은 제외) — 크롭·픽셀 선택과 동일한 정책.
  const panelSplitArmed =
    panelSplitActive &&
    selected?.type === "frame" &&
    !isEffectivelyLocked(selected, groups);
  // 벡터 노드 편집 무장(자유선 요소 선택 + 도구 on) — crop/pixel-select 와 동일한 정책.
  const nodeEditArmed =
    nodeEditTool !== null &&
    selected?.type === "draw" &&
    isNodeEditableKind(selected.kind) &&
    !selectedContentMutationLocked;
  // Referentially stable so memoized panel/overlay children don't re-render on unrelated commits.
  const nodeEditHandles: NodeEditHandle[] = useMemo(
    () =>
      nodeEditArmed && selected?.type === "draw"
        ? decimateStrokeHandles(nodeEditDraft?.elId === selected.id ? nodeEditDraft.points : selected.points, {
            minSpacingPx: NODE_EDIT_DEFAULT_MIN_SPACING_PX / effScale,
            maxHandles: NODE_EDIT_DEFAULT_MAX_HANDLES,
          })
        : EMPTY_NODE_EDIT_HANDLES,
    [nodeEditArmed, selected, nodeEditDraft, effScale]
  );
  // 말풍선 커스텀 모양 점 편집 무장(bubble 선택 + customShapePoints 존재 + 편집 토글 on) — crop/
  // node-edit 과 동일한 정책. decimateStrokeHandles 대신 전부를 핸들로(폴리곤은 이미 성글다).
  const bubbleShapeArmed =
    bubbleShapeEditActive &&
    selected?.type === "bubble" &&
    hasCustomBubbleShape(selected.customShapePoints) &&
    !selectedContentMutationLocked;
  const bubbleShapeHandles: NodeEditHandle[] = useMemo(
    () =>
      bubbleShapeArmed && selected?.type === "bubble"
        ? bubbleShapePointHandles(
            bubbleShapeDraft?.elId === selected.id ? bubbleShapeDraft.points : (selected.customShapePoints ?? [])
          )
        : EMPTY_NODE_EDIT_HANDLES,
    [bubbleShapeArmed, selected, bubbleShapeDraft]
  );
  const smudgeArmed =
    smudgeActive && !smudgeBusy && selected?.type === "image" && !selectedContentMutationLocked;
  const liquifyArmed =
    liquifyActive && !liquifyBusy && selected?.type === "image" && !selectedContentMutationLocked;
  useEffect(() => {
    if (!liquifyArmed) cancelLiquifyPointerSession();
  }, [cancelLiquifyPointerSession, liquifyArmed]);
  const healCloneArmed =
    healCloneTool !== null && selected?.type === "image" && !selectedContentMutationLocked;
  const layerMaskPaintArmed =
    layerMaskPaintActive && selected?.type === "image" && !selectedContentMutationLocked;
  const historyBrushArmed =
    historyBrushActive && selected?.type === "image" && !selectedContentMutationLocked;
  // 퍼펫 워프 무장(이미지 요소 선택 + 모드 on) — crop과 동일한 정책(무장 중 다른 스테이지
  // 제스처·요소 드래그/선택 전환을 막는다).
  const puppetWarpArmed =
    puppetWarpActive && selected?.type === "image" && !selectedContentMutationLocked;
  const contextMenuEl = contextMenu.elId ? (elementById.get(contextMenu.elId) ?? null) : null;
  const resolveBg3dEditSource = useCallback(
    (
      element: El | null
    ): {
      readonly scene?: StudioBg3dSceneDocument;
      readonly legacyDataUrl?: string;
    } | null => {
      if (!element || element.type !== "image") return null;
      if (element.bg3dScene) return { scene: element.bg3dScene };
      if (element.bg3dLtBundleId) {
        const anchor = elements.find(
          (candidate): candidate is ImageEl =>
            candidate.type === "image" &&
            candidate.bg3dLtBundleId === element.bg3dLtBundleId &&
            candidate.bg3dScene !== undefined
        );
        if (anchor?.bg3dScene) return { scene: anchor.bg3dScene };
      }
      return parseStudio3dTool(element.src) === "bg3d" ? { legacyDataUrl: element.src } : null;
    },
    [elements]
  );
  // Referentially stable so the memoized inspector child doesn't re-render on unrelated commits.
  const selectedBg3dEditSource = useMemo(
    () => resolveBg3dEditSource(selected),
    [selected, resolveBg3dEditSource]
  );
  const contextMenuBg3dEditSource = resolveBg3dEditSource(contextMenuEl);
  const showQuickStart = !canvasOnlyMode && !menu && (
    quickStartOpen ||
    (workHydrated && !hasAutosave && elements.length === 0 && !quickStartDismissed)
  );

  // 삭제된 요소의 노드 참조가 nodeRefs에 남지 않도록 정리(누수 방지).
  useEffect(() => {
    const ids = new Set(elements.map((e) => e.id));
    for (const id of Object.keys(nodeRefsRef.current)) {
      if (!ids.has(id)) delete nodeRefsRef.current[id];
    }
  }, [elements]);

  // 내보내기·게시 캡처가 시작되면 마스터 편집 모드를 자동 종료한다 — 캡처 화면은 항상
  // "페이지 요소 + 마스터 합성"이어야 하고, 마스터 편집 화면(고스트 포함)이 찍히면 안 된다.
  useEffect(() => {
    if (isExporting) setMasterEditMode(false);
  }, [isExporting]);

  // 기존 작품 로드 또는 리믹스 대상 로드.
  useEffect(() => {
    const targetId = workId || remixId;
    if (!targetId) {
      setSharedDocumentScope(null);
      setLoadedWork(null);
      setWorkHydrationFailed(false);
      setWorkHydrationUnsupportedFormat(false);
      setWorkHydrated(true);
      return;
    }
    const resolvedTargetId = targetId;
    setWorkHydrated(false);
    setWorkHydrationFailed(false);
    setWorkHydrationUnsupportedFormat(false);
    setSharedDocumentScope(null);
    setLoadedWork(null);
    setError(null);
    setSharedDocumentNotice(null);
    let alive = true;
    const controller = new AbortController();
    async function loadStudioWork(): Promise<{
      work: {
        title: string;
        description: string;
        tags: string[];
        format: "cuttoon" | "upload";
        doc: Record<string, unknown>;
      };
      remixAuthorName: string;
      shared: StudioSharedDocument | null;
      detail: WorkDetail | null;
    }> {
      if (workId && workAuthScopeKey) {
        const { getStudioSharedDocument } = await import("./studio-shared-document-client");
        const shared = await getStudioSharedDocument(workId, controller.signal);
        return {
          work: shared.document,
          remixAuthorName: "",
          shared,
          // shared snapshot에 이미 cover/pages/doc/revision이 모두 있어 초기 full getWork 중복 요청은 없다.
          detail: null,
        };
      }

      // 리믹스와 비로그인 공개 작품 열람은 기존 public getWork 흐름을 그대로 유지한다.
      const { getWork } = await import("@/src/infrastructure/creator-client");
      const publicWork = await getWork(resolvedTargetId, controller.signal);
      return {
        work: publicWork,
        remixAuthorName: publicWork.author.name,
        shared: null,
        detail: !remixId ? publicWork : null,
      };
    }

    void Promise.all([
      loadStudioWork(),
      loadStudioReleaseScheduleRuntime(),
    ])
      .then(async ([
        { work: w, remixAuthorName, shared, detail },
        { normalizeStudioReleaseSchedule },
      ]) => {
        if (!alive) return;
        if (!isStudioCuttoonSourceFormat(w.format)) {
          setWorkHydrationFailed(true);
          setWorkHydrationUnsupportedFormat(true);
          setError("업로드형 작품은 컷툰 편집기로 열 수 없어요. 업로드 편집 화면에서 수정해 주세요.");
          return;
        }
        const doc = w.doc as {
          elements?: El[];
          bg?: string;
          bgGrad?: string[] | null;
          height?: number;
          webtoonTheme?: "classic" | "soft" | "vivid";
          pagesList?: PageState[];
          currentPageId?: string;
          panelGutter?: number;
          master?: unknown; // 문서 마스터(공통 요소) — studio-master-page 옵셔널 규약(과거 문서 미존재 허용).
          characterBible?: unknown;
          writerRoom?: unknown;
          aiProvenance?: unknown;
          comments?: unknown;
          releaseSchedule?: unknown;
          publicationAnalytics?: unknown;
          referenceBoard?: unknown;
          publishPack?: unknown;
        };
        const normalizedPublicationAnalytics = remixId
          ? createEmptyStudioPublicationAnalyticsSnapshot()
          : await normalizeStudioPublicationAnalyticsDeferred(doc?.publicationAnalytics);
        // Optional analytics must not make a document without analytics depend on its chunk, and
        // every async dependency still settles before the single hydration mutation begins.
        if (!alive) return;
        const hydratedProject = creatorWorkSnapshotToStudioProject(w);
        // Server hydration is one canonical document replacement. Advance the async mutation
        // barrier once, then use the raw React setters so this route-scoped effect does not depend
        // on render-local guarded setter identities (and cannot re-run on every document render).
        const hydrationGeneration = collaborationAccessRef.current;
        studioRevisionProjectGenerationRef.current += 1;
        collaborationAccessRef.current = {
          ...hydrationGeneration,
          documentGeneration: hydrationGeneration.documentGeneration + 1,
        };
        if (shared && workAuthScopeKey && workId) {
          setSharedDocumentScope({ authScopeKey: workAuthScopeKey, workId, value: shared });
        }
        setLoadedWork(detail);
        // 리믹스는 새 작품으로 저장되는 별개 문서라 원본의 컷별 연출(fx) 설정을 승계하지 않는다.
        if (remixId) {
          setTitleState(w.title + " (리믹스)");
          setDescriptionState(
            `이 작품은 ${remixAuthorName} 작가님의 '${w.title}' 작품을 리믹스(이어서 편집)한 작품입니다.\n\n${w.description}`
          );
          const rawTags = w.tags ?? [];
          const combinedTags = rawTags.includes("리믹스") ? rawTags : [...rawTags, "리믹스"];
          setTagsTextState(combinedTags.join(", "));
        } else {
          setTitleState(w.title);
          setDescriptionState(w.description);
          setTagsTextState((w.tags ?? []).join(", "));
        }
        advancedFillRunIdRef.current += 1;
        advancedFillAbortRef.current?.abort();
        advancedFillAbortRef.current = null;
        advancedFillTapGestureRef.current = null;
        advancedFillTapPayloadRef.current = null;
        advancedFillTouchPanRef.current = null;
        setAdvancedFillActive(false);
        setAdvancedFillBusy(false);
        setAdvancedFillPreview(null);
        setAdvancedFillStatus(null);
        const hydratedPages = hydratedProject.pagesList as PageState[];
        setPagesHistoryState([hydratedPages]);
        setPagesHiState(0);
        setCurrentPageId(
          hydratedProject.currentPageId &&
          hydratedPages.some((page) => page.id === hydratedProject.currentPageId)
            ? hydratedProject.currentPageId
            : hydratedPages[0].id
        );
        // 문서 마스터(공통 요소) — 과거 문서(master 미존재)는 빈 마스터로(하위호환). 리믹스도 마스터를 승계한다.
        setMasterState(normalizeDocumentMaster(doc?.master) as DocumentMaster<El>);
        setCharacterBibleState(normalizeStudioCharacterBible(doc?.characterBible));
        setWriterRoomState(
          remixId
            ? createEmptyStudioWriterRoomDocument()
            : normalizeStudioWriterRoomDocument(doc?.writerRoom)
        );
        setAiProvenanceState(
          remixId
            ? resetStudioAiProvenanceForRemix()
            : recoverInterruptedStudioAiOperations(
                normalizeStudioAiProvenanceDocument(doc?.aiProvenance)
              )
        );
        setStudioCommentsState(
          remixId ? createEmptyStudioCommentsDocument() : normalizeStudioCommentsDocument(doc?.comments)
        );
        setReleaseScheduleState(
          remixId
            ? createEmptyStudioReleaseScheduleSnapshot()
            : normalizeStudioReleaseSchedule(doc?.releaseSchedule)
        );
        setPublicationAnalyticsState(normalizedPublicationAnalytics);
        setReferenceBoardState(
          remixId
            ? createDefaultStudioReferenceBoardDocument()
            : normalizeStudioReferenceBoardDocument(hydratedProject.referenceBoard)
        );
        if (doc?.webtoonTheme) setWebtoonThemeState(doc.webtoonTheme);
        if (doc?.panelGutter) setPanelGutterState(doc.panelGutter);
        const publishPack = normalizeStudioPublishPackSettings(doc?.publishPack);
        setPublishProfileState(publishPack.profile);
        setPublishAiUsageState(publishPack.aiUsage);
        setPublishAiDisclosureState(publishPack.disclosure);
        setPublishComplianceState(
          remixId ? normalizeStudioPublishCompliance(undefined) : publishPack.compliance
        );
        setPublishPackageSettingsState(publishPackageSettingsFromPack(doc?.publishPack));
        setPublishPackageCreditsState(
          remixId ? "" : publishPackageCreditsFromPack(doc?.publishPack)
        );
        setWorkHydrated(true);
      })
      .catch((e) => {
        if (!alive || controller.signal.aborted) return;
        setWorkHydrationFailed(true);
        setError(e instanceof Error ? e.message : "불러오기 실패");
      });
    return () => {
      alive = false;
      controller.abort();
    };
  }, [remixId, workAuthScopeKey, workId]);

  // 시리즈·챌린지 딥링크로 들어온 경우 게시 맥락 배너를 채운다.
  useEffect(() => {
    if (!publishContextSeriesId && !publishContextChallengeId) {
      setPublishContext({});
      return;
    }
    let alive = true;
    const controller = new AbortController();
    async function loadPublishContext() {
      const next: PublishContext = {};
      if (publishContextSeriesId) {
        try {
          const { getSeries } = await import("@/src/infrastructure/creator-client");
          const series = await getSeries(publishContextSeriesId, controller.signal);
          if (!alive) return;
          const maxEpisode = series.episodeList.reduce(
            (max, episode) => Math.max(max, episode.episodeNo ?? 0),
            0
          );
          next.series = {
            id: series.id,
            title: series.title,
            nextEpisodeNo: maxEpisode + 1,
          };
        } catch {
          // 맥락 로드 실패 시 배너만 생략.
        }
      }
      if (publishContextChallengeId) {
        try {
          const { getChallenge } = await import("@/src/infrastructure/creator-client");
          const challenge = await getChallenge(publishContextChallengeId, controller.signal);
          if (!alive) return;
          next.challenge = {
            id: challenge.id,
            title: challenge.title,
            theme: challenge.theme,
          };
        } catch {
          // 맥락 로드 실패 시 배너만 생략.
        }
      }
      if (alive) setPublishContext(next);
    }
    void loadPublishContext();
    return () => {
      alive = false;
      controller.abort();
    };
  }, [publishContextChallengeId, publishContextSeriesId]);

  useEffect(() => {
    studioOptionalAssetsMountedRef.current = true;
    return () => {
      studioOptionalAssetsMountedRef.current = false;
    };
  }, []);

  useEffect(() => {
    if (menu !== "template") return;
    if (panelLayoutPresets.length > 0 || panelLayoutsLoadRef.current) return;

    setPanelLayoutsLoading(true);
    setPanelLayoutsError(null);
    panelLayoutsLoadRef.current = import("./studio-panel-layouts")
      .then((mod) => {
        if (!studioOptionalAssetsMountedRef.current) return;
        setPanelLayoutPresets(mod.PANEL_LAYOUTS);
      })
      .catch((err) => {
        console.error("Failed to load studio panel layouts:", err);
        panelLayoutsLoadRef.current = null;
        if (studioOptionalAssetsMountedRef.current) {
          setPanelLayoutsError("컷 레이아웃을 불러오지 못했습니다.");
        }
      })
      .finally(() => {
        if (studioOptionalAssetsMountedRef.current) {
          setPanelLayoutsLoading(false);
        }
      });
  }, [menu, panelLayoutPresets.length]);

  useEffect(() => {
    if (menu !== "scene") return;
    if (sceneTemplatePacks || sceneTemplatesLoadRef.current) return;

    setSceneTemplatesLoading(true);
    setSceneTemplatesError(null);
    sceneTemplatesLoadRef.current = import("./studio-scene-templates")
      .then((mod) => {
        if (!studioOptionalAssetsMountedRef.current) return;
        setSceneTemplatePacks({
          categories: mod.SCENE_TEMPLATE_CATEGORIES,
          templates: mod.SCENE_TEMPLATES,
        });
      })
      .catch((err) => {
        console.error("Failed to load studio scene templates:", err);
        sceneTemplatesLoadRef.current = null;
        if (studioOptionalAssetsMountedRef.current) {
          setSceneTemplatesError("장면 템플릿을 불러오지 못했습니다.");
        }
      })
      .finally(() => {
        if (studioOptionalAssetsMountedRef.current) {
          setSceneTemplatesLoading(false);
        }
      });
  }, [menu, sceneTemplatePacks]);

  useEffect(() => {
    if (menu !== "sticker") return;
    if (sfxPacks || sfxLoadRef.current) return;

    setSfxLoading(true);
    setSfxError(null);
    sfxLoadRef.current = import("./studio-sfx-presets")
      .then((mod) => {
        if (!studioOptionalAssetsMountedRef.current) return;
        setSfxPacks({
          categories: mod.SFX_CATEGORIES,
          presets: mod.SFX_LIBRARY,
        });
      })
      .catch((err) => {
        console.error("Failed to load studio SFX presets:", err);
        sfxLoadRef.current = null;
        if (studioOptionalAssetsMountedRef.current) {
          setSfxError("효과음 프리셋을 불러오지 못했습니다.");
        }
      })
      .finally(() => {
        if (studioOptionalAssetsMountedRef.current) {
          setSfxLoading(false);
        }
      });
  }, [menu, sfxPacks]);

  useEffect(() => {
    if (menu !== "bgScene") return;
    if (studioBgSceneAssetsLoaded || bgSceneAssetsLoadRef.current) return;

    setStudioBgSceneAssetsLoading(true);
    setStudioBgSceneAssetsError(null);
    bgSceneAssetsLoadRef.current = Promise.all([
      import("./studio-bg-scenes"),
      import("./studio-bg-scenes-extra"),
    ])
      .then(([bgScenes, bgScenesExtra]) => {
        if (!studioOptionalAssetsMountedRef.current) return;
        const allScenes = [...bgScenes.BG_SCENES, ...bgScenesExtra.BG_SCENES_EXTRA];
        setStudioOptionalAssets((prev) => ({
          ...prev,
          bgSceneSections: bgScenes.bgSceneSections(allScenes),
          bgSceneGenreGroups: bgScenes.groupBgScenes(allScenes),
        }));
        setStudioBgSceneAssetsLoaded(true);
      })
      .catch((err) => {
        console.error("Failed to load studio background scenes:", err);
        bgSceneAssetsLoadRef.current = null;
        if (studioOptionalAssetsMountedRef.current) {
          setStudioBgSceneAssetsError("배경 씬을 불러오지 못했습니다.");
        }
      })
      .finally(() => {
        if (studioOptionalAssetsMountedRef.current) {
          setStudioBgSceneAssetsLoading(false);
        }
      });
  }, [menu, studioBgSceneAssetsLoaded]);

  useEffect(() => {
    if (menu !== "sticker") return;
    if (studioStickerAssetsLoaded || stickerAssetsLoadRef.current) return;

    setStudioStickerAssetsLoading(true);
    setStudioStickerAssetsError(null);
    stickerAssetsLoadRef.current = Promise.all([
      import("./studio-fx-assets"),
      import("./studio-creature-stickers"),
      import("./studio-prop-stickers"),
    ])
      .then(([fxAssets, creatureAssets, propAssets]) => {
        if (!studioOptionalAssetsMountedRef.current) return;
        setStudioOptionalAssets((prev) => ({
          ...prev,
          comicVectorStickers: fxAssets.COMIC_VECTOR_STICKERS,
          creatureStickers: creatureAssets.CREATURE_STICKERS,
          propStickers: propAssets.PROP_STICKERS,
          fxOverlays: fxAssets.FX_OVERLAYS,
        }));
        setStudioStickerAssetsLoaded(true);
      })
      .catch((err) => {
        console.error("Failed to load studio sticker assets:", err);
        stickerAssetsLoadRef.current = null;
        if (studioOptionalAssetsMountedRef.current) {
          setStudioStickerAssetsError("스티커 에셋을 불러오지 못했습니다.");
        }
      })
      .finally(() => {
        if (studioOptionalAssetsMountedRef.current) {
          setStudioStickerAssetsLoading(false);
        }
      });
  }, [menu, studioStickerAssetsLoaded]);

  useEffect(() => {
    if (menu !== "emeres") return;
    if (studioEmeresAssetsLoaded || emeresAssetsLoadRef.current) return;

    setStudioEmeresAssetsLoading(true);
    setStudioEmeresAssetsError(null);
    emeresAssetsLoadRef.current = import("./studio-emeres-templates")
      .then((emeres) => {
        if (!studioOptionalAssetsMountedRef.current) return;
        setStudioOptionalAssets((prev) => ({
          ...prev,
          emeresSections: emeres.emeresSections(),
          emeresUnderlayOpacity: emeres.EMERES_DEFAULT_OPACITY,
        }));
        setStudioEmeresAssetsLoaded(true);
      })
      .catch((err) => {
        console.error("Failed to load studio emeres templates:", err);
        emeresAssetsLoadRef.current = null;
        if (studioOptionalAssetsMountedRef.current) {
          setStudioEmeresAssetsError("이메레스 틀을 불러오지 못했습니다.");
        }
      })
      .finally(() => {
        if (studioOptionalAssetsMountedRef.current) {
          setStudioEmeresAssetsLoading(false);
        }
      });
  }, [menu, studioEmeresAssetsLoaded]);

  // 스튜디오 전용 구글폰트 로드 — 텍스트/말풍선은 웹툰 원고 대부분에서 쓰이므로 "첫 사용 시점까지
  // 기다렸다 로드"하면 정확히 그 첫 사용 순간에 폴백 폰트로 잠깐 그려졌다가 폰트 도착 후 다시
  // 그려지는 깜빡임이 났다(Konva 캔버스 텍스트는 DOM과 달리 폰트 스왑을 스스로 감지하지 못해
  // 수동 재도색이 필요). 대신 마운트 시 requestIdleCallback으로 첫 페인트와 경합 없이 백그라운드
  // 프리로드해, 사용자가 실제로 텍스트를 추가할 즈음엔 대개 이미 도착해 있게 한다.
  // 한 번 로드한 뒤에는 id 가드로 중복 주입을 막고 폰트 캐시는 유지한다.
  useEffect(() => {
    let mounted = true;
    let idleHandle: number | null = null;
    let timeoutHandle: ReturnType<typeof setTimeout> | null = null;
    let removeLoadingDoneListener: (() => void) | null = null;

    const startLoad = () => {
      if (!mounted) return;
      if (!document.getElementById(STUDIO_FONTS_LINK_ID)) {
        const link = document.createElement("link");
        link.id = STUDIO_FONTS_LINK_ID;
        link.rel = "stylesheet";
        link.href = STUDIO_FONTS_CSS2_URL;
        document.head.appendChild(link);
      }
      const redrawStage = () => stageRef.current?.batchDraw();
      // 진행 중이던 로드(전역 폰트 포함)가 정리된 뒤 일회 보정 — 이미 캐시돼 있으면 즉시 실행된다.
      document.fonts.ready.then(() => {
        if (mounted) redrawStage();
      });
      // display=swap 특성상 폰트는 늦게 도착할 수 있다 — 도착할 때마다 보정.
      document.fonts.addEventListener("loadingdone", redrawStage);
      removeLoadingDoneListener = () => document.fonts.removeEventListener("loadingdone", redrawStage);
    };

    const ric = (globalThis as { requestIdleCallback?: (cb: () => void) => number }).requestIdleCallback;
    if (typeof ric === "function") {
      idleHandle = ric(startLoad);
    } else {
      timeoutHandle = setTimeout(startLoad, 300);
    }

    return () => {
      mounted = false;
      const cic = (globalThis as { cancelIdleCallback?: (handle: number) => void }).cancelIdleCallback;
      if (idleHandle !== null && typeof cic === "function") cic(idleHandle);
      if (timeoutHandle !== null) clearTimeout(timeoutHandle);
      removeLoadingDoneListener?.();
    };
  }, []);

  // 커스텀 에셋 라이브러리 목록 불러오기 및 관리
  const loadAssetsList = async () => {
    setAssetsLoading(true);
    try {
      const { listAssets } = await import("./studio-asset-library");
      const list = await listAssets();
      setAssets(list);
    } catch (err) {
      console.error("Failed to load custom assets:", err);
      setAssets([]);
    } finally {
      setAssetsLoading(false);
    }
  };

  useEffect(() => {
    if (menu === "asset") {
      loadAssetsList();
    }
  }, [menu]);

  async function onUploadAsset(e: React.ChangeEvent<HTMLInputElement>) {
    const file = e.target.files?.[0];
    if (!file) return;
    try {
      const { src, width, height } = await loadImageFileForCanvas(file);
      const { saveAsset } = await import("./studio-asset-library");
      await saveAsset({ name: file.name, dataUrl: src, width, height });
      await loadAssetsList();
    } catch (err) {
      setError(err instanceof Error ? err.message : "에셋 업로드 실패");
    } finally {
      e.target.value = "";
    }
  }

  async function onDeleteAsset(id: string) {
    try {
      const { deleteAsset } = await import("./studio-asset-library");
      await deleteAsset(id);
      removeAssetFavorite(createStudioAssetFavoriteId("local", id));
      await loadAssetsList();
    } catch (err) {
      setError(err instanceof Error ? err.message : "에셋 삭제 실패");
    }
  }

